    "name": "CabCheckbox",
    "description": "A checkbox for a yes/no choice that is confirmed later (e.g. on form submit). Native `<input type=\"checkbox\">` with a chunky custom box; native semantics are kept.",
    "import": "import { CabCheckbox } from '@eltonbautista/vue'"
