  {
    "name": "CabDialog",
    "description": "A modal dialog for a short, focused task or a confirmation that must be answered before continuing. Built on the native `<dialog>` with `showModal()`, so the page behind it is inert.",
    "import": "import { CabDialog } from '@eltonbautista/vue'"
  },
  {
    "name": "CabSelect",
    "description": "A select-only combobox: pick one value from a short list of options. Follows the APG \"Select-Only Combobox\" pattern; focus never leaves the combobox.",
    "import": "import { CabSelect } from '@eltonbautista/vue'"
  },
  {
    "name": "CabSwitch",
    "description": "An on/off switch for a setting that takes effect immediately. A `<button role=\"switch\">` labelled by a native `<label>`.",
    "import": "import { CabSwitch } from '@eltonbautista/vue'"
  },
  {
    "name": "CabTabs",
    "description": "Tabs that switch between related panels of content in place. Follows the APG Tabs pattern with roving tabindex and automatic or manual activation.",
    "import": "import { CabTabs } from '@eltonbautista/vue'"
  },
  {
    "name": "CabTextField",
    "description": "A single-line text input with a visible label, optional hint and an error message. Errors are announced through `aria-describedby` and marked with `aria-invalid`.",
    "import": "import { CabTextField } from '@eltonbautista/vue'"
  }
]

