{
  "name": "CabCard",
  "import": "import { CabCard } from '@eltonbautista/vue'",
  "description": "A content container with a soft ledge, for grouping a title, media, text and actions. Not interactive by itself; pass `href` to make the whole card a link through its title.",
  "props": [
    {
      "name": "as",
      "type": "\"article\" | \"section\" | \"div\"",
      "required": false,
      "default": "\"article\"",
      "description": "Element to render. `article` for self-contained content (default), `section` or `div` otherwise."
    },
    {
      "name": "title",
      "type": "string",
      "required": false,
      "description": "Card title, rendered as a heading."
    },
    {
      "name": "headingLevel",
      "type": "2 | 3 | 4",
      "required": false,
      "default": "3",
      "description": "Heading level for the title, to fit the page outline."
    },
    {
      "name": "href",
      "type": "string",
      "required": false,
      "description": "Makes the title a link and stretches its hit area over the whole card."
    }
  ],
  "types": [],
  "events": [],
  "slots": [
    {
      "name": "media",
      "type": "any",
      "description": "Image or illustration above the content. Give images meaningful `alt` text, or `alt=\"\"` if decorative."
    },
    {
      "name": "default",
      "type": "any",
      "description": "Body content."
    },
    {
      "name": "footer",
      "type": "any",
      "description": "Actions or meta row at the bottom."
    }
  ],
  "a11y": {
    "summary": "A container with a soft ledge for grouping related content: a title, optional media, text and actions. Cards aren't interactive by themselves. To make a whole card open something, pass `href`: the title becomes a link whose hit area covers the card, so there is still exactly one link to tab to and one name to announce. Don't nest cards.",
    "pattern": "No ARIA widget pattern: semantic HTML. Rendered as `<article>` by default (self-contained content), labelled by its title. Use `as=\"section\"` for a titled region of a page, or `as=\"div\"` when the card is purely visual. The whole-card link uses the [stretched link technique](https://inclusive-components.design/cards/) rather than wrapping everything in `<a>`, which would make screen readers read the entire card as the link name.",
    "keyboard": "| Key | Action |\n| --- | --- |\n| Tab / Shift+Tab | Moves through interactive content inside the card (and the title link when `href` is set). The card itself is not a tab stop. |\n| Enter | Follows the title link when `href` is set. |",
    "focus": "With `href`, the 3px purple focus ring is drawn around the whole card while its title link has keyboard focus (`:has(:focus-visible)`), matching the clickable area. Without `href`, only the controls inside the card take focus.",
    "screenReader": "An article is announced with its title as the name, and the title is a heading at `headingLevel` (default 3) so cards appear in the page's heading outline. With `href`, the link's name is just the title, not the whole card's text. Give `media` images real `alt` text, or `alt=\"\"` when decorative."
  },
  "examples": [
    {
      "name": "Basic",
      "description": "A content card with a tag, body text and an action."
    },
    {
      "name": "Clickable",
      "description": "A whole card that links somewhere, using href (stretched title link)."
    }
  ]
}

