{
  "name": "CabTextField",
  "import": "import { CabTextField } from '@eltonbautista/vue'",
  "description": "A single-line text input with a visible label, optional hint and an error message. Errors are announced through `aria-describedby` and marked with `aria-invalid`.",
  "props": [
    {
      "name": "modelValue",
      "type": "string",
      "required": true,
      "description": "Current value (use `v-model`)."
    },
    {
      "name": "label",
      "type": "string",
      "required": true,
      "description": "Visible label. Required: placeholders are not labels."
    },
    {
      "name": "hint",
      "type": "string",
      "required": false,
      "description": "Helper text shown under the label and announced after it."
    },
    {
      "name": "error",
      "type": "string",
      "required": false,
      "description": "Error message. When set, the field is marked invalid and the message is announced."
    },
    {
      "name": "type",
      "type": "\"text\" | \"email\" | \"password\" | \"tel\" | \"url\" | \"search\"",
      "required": false,
      "default": "\"text\"",
      "description": "Native input type."
    },
    {
      "name": "required",
      "type": "boolean",
      "required": false,
      "default": "false",
      "description": "Marks the field required (native `required` plus a visual asterisk)."
    },
    {
      "name": "disabled",
      "type": "boolean",
      "required": false,
      "default": "false",
      "description": "Disables the field."
    },
    {
      "name": "autocomplete",
      "type": "string",
      "required": false,
      "description": "Native `autocomplete` token, e.g. `email` or `name`."
    },
    {
      "name": "placeholder",
      "type": "string",
      "required": false,
      "description": "Placeholder example text. Never a substitute for `label` or `hint`."
    }
  ],
  "types": [],
  "events": [
    {
      "name": "update:modelValue",
      "type": "[value: string]",
      "description": ""
    }
  ],
  "slots": [],
  "a11y": {
    "summary": "A single-line text input with a visible label, optional hint and error message. Use it for short free text such as names and email addresses. The label is always visible; placeholders are only for example values.",
    "pattern": "Native `<input>` with a `<label for>` association. Hint and error follow the [WAI form instructions](https://www.w3.org/WAI/tutorials/forms/instructions/) and [validation](https://www.w3.org/WAI/tutorials/forms/notifications/) guidance.",
    "keyboard": "| Key | Action |\n| --- | --- |\n| Tab / Shift+Tab | Moves focus to and from the field. |\n| Any character | Edits the value. |",
    "focus": "A 3px purple ring with a 3px offset on keyboard focus. The border also darkens on hover. Invalid fields keep a red border and add a drawn warning icon, so colour is never the only signal.",
    "screenReader": "Announced as \"*label*, edit text\", plus \"required\" and \"invalid entry\" when they apply. The hint and the error are linked with `aria-describedby` (hint first, then error), so both are read after the label. The required asterisk is hidden from assistive tech because the native `required` attribute already announces it."
  },
  "examples": [
    {
      "name": "Basic",
      "description": "A labelled text field bound with v-model."
    },
    {
      "name": "WithError",
      "description": "Showing a validation error that names the problem and the fix."
    },
    {
      "name": "WithHint",
      "description": "A required email field with hint text."
    }
  ]
}

