{
  "name": "CabSelect",
  "import": "import { CabSelect } from '@eltonbautista/vue'",
  "description": "A select-only combobox: pick one value from a short list of options. Follows the APG \"Select-Only Combobox\" pattern; focus never leaves the combobox.",
  "props": [
    {
      "name": "modelValue",
      "type": "string | null",
      "required": true,
      "description": "Selected value (use `v-model`). `null` shows the placeholder."
    },
    {
      "name": "label",
      "type": "string",
      "required": true,
      "description": "Visible label."
    },
    {
      "name": "options",
      "type": "CabSelectOption[]",
      "required": true,
      "description": "The options, in display order."
    },
    {
      "name": "placeholder",
      "type": "string",
      "required": false,
      "default": "\"Select…\"",
      "description": "Text shown when nothing is selected."
    },
    {
      "name": "hint",
      "type": "string",
      "required": false,
      "description": "Helper text linked with `aria-describedby`."
    },
    {
      "name": "error",
      "type": "string",
      "required": false,
      "description": "Error message; marks the combobox invalid and is announced."
    },
    {
      "name": "disabled",
      "type": "boolean",
      "required": false,
      "default": "false",
      "description": "Disables the select."
    }
  ],
  "types": [
    "export interface CabSelectOption {\n  /** Value emitted through `v-model`. */\n  value: string\n  /** Visible option text (also used for typeahead). */\n  label: string\n  /** Disabled options are shown but cannot be chosen or reached with the keyboard. */\n  disabled?: boolean\n}"
  ],
  "events": [
    {
      "name": "update:modelValue",
      "type": "[value: string]",
      "description": ""
    }
  ],
  "slots": [],
  "a11y": {
    "summary": "Choose one value from a short list (roughly 3 to 15 options). Use it when the options don't fit comfortably as radio buttons. For long or searchable lists, a different pattern is needed. The label is always visible; the placeholder only says nothing is selected yet.",
    "pattern": "[WAI-ARIA APG: Select-Only Combobox](https://www.w3.org/WAI/ARIA/apg/patterns/combobox/examples/combobox-select-only/). A `role=\"combobox\"` element controls a `role=\"listbox\"` popup. DOM focus never leaves the combobox; the highlighted option is conveyed with `aria-activedescendant`.",
    "keyboard": "| Key | Action |\n| --- | --- |\n| ↓ / ↑ / Enter / Space / Alt+↓ | Opens the list on the selected option (or the first option). |\n| Home / End | Opens the list on the first / last option. |\n| ↓ / ↑ (open) | Moves to the next / previous option, skipping disabled ones. Stops at the ends. |\n| Home / End (open) | Moves to the first / last option. |\n| Page Down / Page Up (open) | Moves 10 options. |\n| Enter / Space / Alt+↑ (open) | Selects the highlighted option and closes. |\n| Tab (open) | Selects the highlighted option, closes, and moves focus on. |\n| Escape (open) | Closes without changing the value. |\n| Letters | Opens the list and jumps to the next option starting with the typed text (500ms buffer). |",
    "focus": "The combobox shows the 3px purple focus ring. Inside the open list, the highlighted option gets a purple inset outline and a tinted background, so it's visible without relying on colour alone. Clicking an option returns focus to the combobox. Clicking elsewhere closes the list.",
    "screenReader": "Announced as \"*label*, combobox, collapsed, *selected value*\". When open, each highlighted option is read as \"*option*, selected/not selected, 2 of 4\". Disabled options stay in the list with `aria-disabled=\"true\"` so people know they exist. Hint and error are linked with `aria-describedby`, and errors set `aria-invalid`."
  },
  "examples": [
    {
      "name": "Basic",
      "description": "A select bound with v-model, with a hint and a disabled option."
    },
    {
      "name": "WithError",
      "description": "A required select showing a validation error."
    }
  ]
}

