      "type": "string",
      "required": false,
      "description": "Helper text linked with `aria-describedby`."
    },
    {
      "name": "disabled",
      "type": "boolean",
      "required": false,
      "default": "false",
      "description": "Disables the checkbox."
    }
  ],
  "types": [],
  "events": [
    {
      "name": "update:modelValue",
      "type": "[value: boolean]",
      "description": ""
    }
  ],
  "slots": [],
