{
  "name": "CabDialog",
  "import": "import { CabDialog } from '@eltonbautista/vue'",
  "description": "A modal dialog for a short, focused task or a confirmation that must be answered before continuing. Built on the native `<dialog>` with `showModal()`, so the page behind it is inert.",
  "props": [
    {
      "name": "open",
      "type": "boolean",
      "required": true,
      "description": "Whether the dialog is open (use `v-model:open`)."
    },
    {
      "name": "title",
      "type": "string",
      "required": true,
      "description": "Visible title; also the dialog's accessible name."
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Optional one-line description, announced after the title."
    },
    {
      "name": "closeLabel",
      "type": "string",
      "required": false,
      "default": "\"Close\"",
      "description": "Accessible name of the close button."
    }
  ],
  "types": [],
  "events": [
    {
      "name": "update:open",
      "type": "[value: boolean]",
      "description": ""
    }
  ],
  "slots": [
    {
      "name": "default",
      "type": "any",
      "description": "Dialog body. The first focusable element here receives focus on open."
    },
    {
      "name": "footer",
      "type": "any",
      "description": "Actions row, e.g. Cancel and Confirm buttons."
    }
  ],
  "a11y": {
    "summary": "A modal dialog for a short task or a decision that must be made before going back to the page, like confirming a booking. Don't use it for content people may want to read alongside the page. Keep it short: a title, a sentence or a small form, and one or two actions.",
    "pattern": "[WAI-ARIA APG: Dialog (Modal)](https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/). Built on the native `<dialog>` opened with `showModal()`, which makes the rest of the page inert for free: it can't be clicked, focused or read while the dialog is open. Named by its title (`aria-labelledby`) and described by `description` (`aria-describedby`).",
    "keyboard": "| Key | Action |\n| --- | --- |\n| Tab / Shift+Tab | Moves between focusable elements inside the dialog, wrapping from last to first and first to last. |\n| Escape | Closes the dialog (emits `update:open` `false`). |\n| Enter / Space | Activates the focused button. |",
    "focus": "On open, focus moves to the first focusable element in the body; if there is none, it goes to the close button. Focus stays inside while the dialog is open. On close, focus returns to the element that opened it, or stays safely on the page if that element has since been removed. The close button and actions show the 3px purple focus ring.",
    "screenReader": "Announced as \"*title*, dialog\", followed by the description. The close button has a visually hidden text label (`closeLabel`, default \"Close\") and its icon is hidden from assistive tech. With reduced motion, the dialog fades instead of rising and scaling."
  },
  "examples": [
    {
      "name": "Basic",
      "description": "A dialog opened from a button, with a form field and actions."
    },
    {
      "name": "Confirm",
      "description": "A confirmation with no form fields; focus starts on the first action."
    }
  ]
}

